import zipfile, xml.etree.ElementTree as ET, re, json, collections, html, pathlib
source='REKOD PERMOHONAN KSAS 1.xlsx';out='index.html'
z=zipfile.ZipFile(source);ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
ss=[''.join(e.itertext()) for e in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',ns)]
root=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
records=[]
for row in root.findall('m:sheetData/m:row',ns)[3:]:
 d={}
 for c in row.findall('m:c',ns):
  v=c.find('m:v',ns);ins=c.find('m:is',ns);t=v.text if v is not None else ''.join(ins.itertext()) if ins is not None else ''
  if c.attrib.get('t')=='s' and t:t=ss[int(t)]
  d[re.match('[A-Z]+',c.attrib['r']).group()]=str(t or '').strip()
 if re.fullmatch(r'20\d\d',d.get('E','')):
  records.append(dict(bil=d.get('A',''),pemohon=d.get('B',''),pbt=d.get('D','') or 'Tidak Dinyatakan',tahun=int(d['E']),status=d.get('F','') or 'BELUM DIREKODKAN',tajuk=d.get('H',''),kelulusan=d.get('G','')))
data=json.dumps(records,ensure_ascii=False).replace('</','<\\/')
template=r'''<!DOCTYPE html><html lang="ms"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard KSAS Negeri Selangor</title><style>
:root{--bg:#f3f6f9;--nav:#102a32;--ink:#18313b;--muted:#6d8290;--border:#e2e9ed;--green:#0b8e78;--amber:#e5a23a;--red:#ce5966;--blue:#427fa5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,"Segoe UI",Arial,sans-serif;font-size:14px}header{background:#0e2f35;color:white;padding:22px 34px 26px;border-bottom:5px solid #d4aa51}header .small{color:#96cfc4;font-size:11px;font-weight:800;letter-spacing:2.4px}header h1{font-size:27px;margin:8px 0 4px;font-weight:800}header p{margin:0;color:#b7d2d1}.wrap{max-width:1500px;margin:auto;padding:27px 27px 42px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:17px;flex-wrap:wrap}.top h2{font-size:19px;margin:0 0 4px}.top p{color:var(--muted);margin:0;font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{background:white;border:1px solid #d6e1e6;border-radius:9px;padding:10px 14px;cursor:pointer;font-weight:700;color:#294a52}.btn.main{background:var(--green);color:white;border-color:var(--green)}.filters{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:12px;margin-bottom:19px}.filter{background:white;padding:10px 12px;border:1px solid var(--border);border-radius:12px}.filter label{display:block;font-size:11px;font-weight:800;color:var(--muted);margin-bottom:5px;text-transform:uppercase;letter-spacing:.7px}.filter select,.filter input{width:100%;border:none;outline:none;font-size:13px;color:var(--ink);padding:5px 0;background:white}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:18px}.kpi{background:white;border:1px solid var(--border);padding:19px;border-radius:13px;position:relative;overflow:hidden;min-height:112px}.kpi:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--accent)}.kpi span{font-size:12px;color:var(--muted);font-weight:700}.kpi strong{display:block;font-size:31px;margin:8px 0 2px;letter-spacing:-1.2px}.kpi small{font-size:11px;color:#94a5ab}.layout{display:grid;grid-template-columns:1.6fr 1fr;gap:16px}.panel{background:white;border:1px solid var(--border);border-radius:13px;padding:20px 22px;min-width:0}.panel h3{font-size:15px;margin:0 0 4px}.sub{color:var(--muted);font-size:11px;margin-bottom:18px}.wide{grid-column:1/-1}.bars{display:flex;align-items:end;gap:8px;height:218px;padding-bottom:27px;border-bottom:1px solid var(--border)}.barcol{flex:1;min-width:0;position:relative;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:5px}.bar{width:65%;max-width:31px;min-height:2px;background:linear-gradient(180deg,#22b49b,#0c8074);border-radius:5px 5px 0 0;transition:.3s;cursor:default}.bar:hover{filter:brightness(1.16)}.barcol small{position:absolute;bottom:-25px;font-size:10px;color:#72838b}.barcol b{font-size:10px;color:#516b72}.donutwrap{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.donut{width:190px;height:190px;border-radius:50%;position:relative;flex-shrink:0}.donut:after{content:"";position:absolute;inset:43px;background:#fff;border-radius:50%}.center{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;flex-direction:column}.center b{font-size:30px}.center span{font-size:10px;color:var(--muted)}.legend{flex:1;min-width:190px}.legendrow{display:flex;justify-content:space-between;gap:10px;align-items:center;border-bottom:1px solid #eef1f4;padding:9px 0;font-size:12px}.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:8px}.hbars{display:grid;gap:12px}.hrow{display:grid;grid-template-columns:78px 1fr 35px;gap:10px;align-items:center;font-size:12px}.track{height:11px;background:#edf3f3;border-radius:20px;overflow:hidden}.fill{height:100%;background:#1c9c8c;border-radius:20px}.tablewrap{overflow:auto;max-height:450px;border:1px solid var(--border);border-radius:9px}table{width:100%;border-collapse:collapse;font-size:12px;min-width:850px}thead th{position:sticky;top:0;background:#eaf2f3;text-align:left;font-size:11px;padding:13px 12px;z-index:1}td{padding:11px 12px;border-top:1px solid #ebf0f2;vertical-align:top}td:nth-child(4){max-width:480px;line-height:1.45}.pill{display:inline-block;padding:5px 9px;border-radius:18px;font-size:10px;font-weight:800;white-space:nowrap}.empty{padding:30px;color:var(--muted);text-align:center}.meta{color:#738991;font-size:11px;line-height:1.7;margin-top:17px}.footer{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}.count{font-size:12px;color:var(--muted)}@media(max-width:1000px){.kpis{grid-template-columns:repeat(3,1fr)}.filters{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:16px}.kpis{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:1fr}header{padding:21px}.donut{width:160px;height:160px}.bars{gap:3px}.barcol small{font-size:8px;transform:rotate(-42deg)}}@media print{.actions,.filters{display:none}.wrap{max-width:none;padding:12px}.tablewrap{max-height:none}header{print-color-adjust:exact}}

/* Tema rujukan: SUG-inspired civic dashboard */
:root{--bg:#fffaf5;--nav:#fff9f0;--ink:#192943;--muted:#687389;--border:#f0d9c7;--green:#27986c;--amber:#f5a11c;--red:#d91f3d;--blue:#436eb3}
body{background:#f8f7f5;color:var(--ink);font-size:13px}
header{background:linear-gradient(107deg,#fff 0%,#fff 66%,#fffbec 83%,#ffead3 100%);color:var(--ink);border:0;border-bottom:1px solid #efd5be;padding:15px 24px 17px 218px;min-height:91px;position:relative}
header:after{content:' ';position:absolute;right:0;bottom:0;width:240px;height:55px;background:linear-gradient(150deg,transparent 20%,#f7a51b22 20% 26%,transparent 27%),linear-gradient(170deg,transparent 43%,#ec512425 44% 49%,transparent 50%);pointer-events:none}
header .small{color:#df512b;letter-spacing:1.4px;font-size:10px}
header h1{font-size:24px;margin:5px 0 3px;font-weight:850;letter-spacing:-.55px}header p{color:#748092;font-size:12px}
.sidebar{position:fixed;top:91px;bottom:0;left:0;width:196px;z-index:5;background:linear-gradient(#fffaf2,#fff5e8);border-right:1px solid #eddfcc;display:flex;flex-direction:column;padding:13px 10px;gap:5px}
.brand{font-weight:900;font-size:13px;color:#db342e;display:flex;align-items:center;gap:10px;padding:14px 9px;border-bottom:1px solid #ebddcb;margin-bottom:11px}.brand .mark{background:linear-gradient(135deg,#f84c2b,#f6ad18);color:white;border-radius:12px;padding:10px}
.navitem{display:flex;text-decoration:none;align-items:center;gap:10px;padding:12px 11px;font-weight:730;color:#28344d;border-radius:6px;font-size:12px}.navitem span{font-size:15px;color:#e6293f}.navitem.active,.navitem:hover{color:white;background:linear-gradient(95deg,#d92b3a,#f5a516);box-shadow:0 4px 11px #eb744032}.navitem.active span,.navitem:hover span{color:white}.sidefoot{margin-top:auto;font-size:10px;line-height:1.65;color:#bd744f;border-top:1px solid #ead6c4;padding:15px 6px}
.wrap{max-width:none;padding:12px 15px 32px;margin-left:196px}.top{margin-bottom:10px}.top h2{font-size:15px}.top p{font-size:11px}.btn{border-radius:5px;font-size:12px;padding:9px 13px}.btn.main{background:linear-gradient(100deg,#e53b29,#f29c15);border:0;color:white}
.filters{grid-template-columns:1.3fr 1fr 1fr 1.4fr;margin-bottom:10px;gap:7px}.filter{border-radius:5px;padding:6px 9px;background:#fff;border-color:#e6d2c3}.filter label{color:#333f54;letter-spacing:0;text-transform:none;font-size:10px;margin-bottom:3px}.filter select,.filter input{font-size:12px}
.kpis{grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:10px}.kpi{border-radius:6px;min-height:93px;padding:13px 13px 11px;border:1px solid #edd6c2;box-shadow:0 1px 2px #efd5b533}.kpi:before{width:3px;background:var(--accent)}.kpi span{color:#4c586b;font-size:11px}.kpi strong{font-size:28px;margin:6px 0 1px;color:#ae173e}.kpi small{font-size:10px}
.layout{grid-template-columns:minmax(0,1.35fr) minmax(300px,1fr);gap:9px}.panel{border-radius:6px;padding:0 14px 13px;border:1px solid #e9e0da}.panel h3{font-size:12px;margin:0 -14px 12px;padding:11px 13px;color:#d82338;border-left:4px solid #e5323b;border-bottom:1px solid #f0e2dc;background:#fffdfb}.panel:first-child h3{color:white;background:linear-gradient(100deg,#d92138,#f7a11a);border-left-color:#fff}.panel .sub{font-size:10px;margin-top:0;margin-bottom:15px}.panel.wide{grid-column:1/-1}
.bar{background:linear-gradient(#e43b48,#f5ad27)}.bars{height:260px}.track{background:#f9eae0}.fill{background:linear-gradient(90deg,#e22d41,#f5a127)}thead th{background:#f5f3f1;font-size:11px}td{border-color:#f3ece6}.tablewrap{max-height:375px;border-radius:4px}.meta{font-size:10px}.hrow .track{position:relative}.hrow .fill{box-shadow:inset 0 -1px 0 #ffffff33}.pbtlabel{display:flex;align-items:center;gap:8px;font-weight:800;color:#33415a}.pbtlabel .swatch{width:10px;height:10px;border-radius:3px;flex:0 0 10px;box-shadow:0 0 0 1px #ffffffaa inset,0 0 0 1px #d9c7ba}.pbtpill{display:inline-flex;align-items:center;gap:7px;padding:5px 9px;border-radius:999px;font-size:10px;font-weight:800;border:1px solid transparent;background:#fff7ef}.pbtpill .swatch{width:8px;height:8px;border-radius:50%;flex:0 0 8px}.tbodyrow:hover{background:#fff9f2}
@media(max-width:1060px){header{padding-left:190px}.sidebar{width:170px}.wrap{margin-left:170px}.kpis{grid-template-columns:repeat(3,1fr)}}
@media(max-width:760px){header{padding:17px 15px 15px}.sidebar{position:static;width:auto;display:flex;flex-direction:row;overflow:auto;gap:5px;padding:7px}.brand,.sidefoot{display:none}.navitem{white-space:nowrap;padding:9px}.wrap{margin-left:0;padding:10px}.layout{grid-template-columns:1fr}.filters{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(2,1fr)}}
@media(max-width:480px){.filters{grid-template-columns:1fr}.kpis{grid-template-columns:1fr 1fr}header h1{font-size:19px}.top{display:block}.actions{margin-top:10px}.donutwrap{justify-content:center}}
@media print{.sidebar{display:none}.wrap{margin-left:0}header{padding-left:18px}}
</style></head><body><header><div class="small">PLANMalaysia SELANGOR · PEMANTAUAN PERMOHONAN</div><h1>DASHBOARD KSAS NEGERI SELANGOR</h1><p>Jawatankuasa Teknikal Pembangunan Kawasan Sensitif Alam Sekitar (JTPKSAS)</p></header><nav class="sidebar" aria-label="Navigasi dashboard"><div class="brand"><span class="mark">◆</span><span>KSAS SELANGOR</span></div><a class="navitem active" href="#utama"><span>⌂</span>Utama</a><a class="navitem" href="#trend-panel"><span>▥</span>Trend Permohonan</a><a class="navitem" href="#decision-panel"><span>◕</span>Analisis Keputusan</a><a class="navitem" href="#pbt-panel"><span>▤</span>Analisis PBT</a><a class="navitem" href="#rekod-panel"><span>≡</span>Senarai Rekod</a><a class="navitem" href="#rekod-panel" onclick="exportCSV();return false"><span>⇩</span>Muat Turun Data</a><div class="sidefoot">PLANMalaysia Selangor<br>Data permohonan KSAS</div></nav><main class="wrap" id="utama"><section class="top"><div><h2>Analisis Rekod Permohonan</h2><p>Data sejarah 2010–2026 · Paparan interaktif berdasarkan fail rekod yang dibekalkan</p></div><div class="actions"><button class="btn" onclick="resetFilters()">↻ Set Semula</button><button class="btn" onclick="window.print()">⎙ Cetak / PDF</button><button class="btn main" onclick="exportCSV()">↓ Eksport CSV</button></div></section><section class="filters"><div class="filter"><label>Cari pemohon / tajuk</label><input id="search" placeholder="Taip kata kunci..." oninput="render()"></div><div class="filter"><label>Tahun</label><select id="year" onchange="render()"></select></div><div class="filter"><label>Pihak Berkuasa Tempatan</label><select id="pbt" onchange="render()"></select></div><div class="filter"><label>Keputusan</label><select id="status" onchange="render()"></select></div></section><section class="kpis"><div class="kpi" style="--accent:#427fa5"><span>JUMLAH PERMOHONAN</span><strong id="total">0</strong><small>Rekod dalam pemilihan</small></div><div class="kpi" style="--accent:#0b8e78"><span>BERSETUJU</span><strong id="agreed">0</strong><small id="agreedpct">0% daripada jumlah</small></div><div class="kpi" style="--accent:#ce5966"><span>DITOLAK</span><strong id="rejected">0</strong><small id="rejectpct">0% daripada jumlah</small></div><div class="kpi" style="--accent:#e5a23a"><span>DITANGGUHKAN</span><strong id="deferred">0</strong><small>Keputusan ditangguhkan</small></div><div class="kpi" style="--accent:#8196a3"><span>TARIK DIRI / TIADA STATUS</span><strong id="other">0</strong><small>Termasuk status belum direkodkan</small></div></section><section class="layout"><article class="panel" id="trend-panel"><h3>Trend Permohonan Mengikut Tahun</h3><div class="sub">Bilangan permohonan didaftarkan setiap tahun</div><div class="bars" id="trend"></div></article><article class="panel" id="decision-panel"><h3>Pecahan Keputusan</h3><div class="sub">Taburan keputusan permohonan bagi pemilihan semasa</div><div class="donutwrap"><div class="donut" id="donut"><div class="center"><b id="donutTotal">0</b><span>PERMOHONAN</span></div></div><div class="legend" id="legend"></div></div></article><article class="panel wide" id="pbt-panel"><h3>Permohonan Mengikut PBT</h3><div class="sub">PBT paling banyak direkodkan · maksimum 12 PBT</div><div class="hbars" id="pbtBars"></div></article><article class="panel wide" id="rekod-panel"><h3>Senarai Rekod Permohonan</h3><div class="sub">Carian dan penapisan mempengaruhi semua graf dan jadual · paparan 150 rekod pertama</div><div class="tablewrap"><table><thead><tr><th>Bil.</th><th>Tahun</th><th>PBT</th><th>Perkara / Tajuk Permohonan</th><th>Pemohon</th><th>Keputusan</th></tr></thead><tbody id="tbody"></tbody></table></div><div class="footer"><div class="count" id="tableCount"></div><button class="btn" onclick="exportCSV()">Eksport semua rekod ditapis</button></div></article></section><p class="meta"><b>Sumber:</b> “REKOD PERMOHONAN KSAS 1.xlsx”, helaian “rekod”. Analisis menggunakan rekod yang mempunyai nilai tahun 2000–2099. Nama PBT dikekalkan seperti dalam sumber (termasuk singkatan lama); keputusan kosong dikategorikan sebagai “BELUM DIREKODKAN”. Statistik mencerminkan rekod fail yang diberikan dan bukan semestinya status rasmi semasa. Tarikh kelulusan tidak digunakan kerana sebahagian rekod mengandungi format bercampur.</p></main><script>
const data=__DATA__;
const colors={'BERSETUJU':'#0b8e78','DITOLAK':'#ce5966','DITANGGUHKAN':'#e5a23a','TARIK DIRI':'#427fa5','BELUM DIREKODKAN':'#a0b0bb'};
const pbtPalette=['#e24b55','#f07e2d','#efad2b','#d8b83f','#8fc45a','#50ad75','#41aaa1','#5f94cf','#7668c7','#b866bc','#de6a87','#6375b7'];
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const alpha=(hex,a)=>hex.length===7?hex+a:hex;
const mapColors=keys=>Object.fromEntries(keys.map((k,i)=>[k,pbtPalette[i%pbtPalette.length]]));
function options(id,vals,all){$(id).innerHTML='<option value="">'+all+'</option>'+vals.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')}
options('year',[...new Set(data.map(r=>r.tahun))].sort((a,b)=>b-a),'Semua Tahun');options('pbt',[...new Set(data.map(r=>r.pbt))].sort((a,b)=>a.localeCompare(b)),'Semua PBT');options('status',Object.keys(colors),'Semua Keputusan');
function selected(){const q=$('search').value.toLocaleLowerCase('ms').trim(),y=$('year').value,p=$('pbt').value,s=$('status').value;return data.filter(r=>(!y||r.tahun==y)&&(!p||r.pbt===p)&&(!s||r.status===s)&&(!q||[r.pemohon,r.tajuk,r.pbt,r.bil].join(' ').toLocaleLowerCase('ms').includes(q)))}
function render(){let r=selected(),n=r.length,count=s=>r.filter(x=>x.status===s).length,pct=x=>n?(100*x/n).toFixed(1)+'%':'0%';$('total').textContent=n.toLocaleString('ms-MY');$('agreed').textContent=count('BERSETUJU');$('rejected').textContent=count('DITOLAK');$('deferred').textContent=count('DITANGGUHKAN');$('other').textContent=count('TARIK DIRI')+count('BELUM DIREKODKAN');$('agreedpct').textContent=pct(count('BERSETUJU'))+' daripada jumlah';$('rejectpct').textContent=pct(count('DITOLAK'))+' daripada jumlah';
const years=[...new Set(data.map(x=>x.tahun))].sort((a,b)=>a-b),yv=years.map(y=>r.filter(x=>x.tahun===y).length),max=Math.max(1,...yv);$('trend').innerHTML=years.map((y,i)=>'<div class="barcol" title="'+y+': '+yv[i]+' permohonan"><b>'+ (yv[i]||'') +'</b><div class="bar" style="height:'+Math.max(1,yv[i]/max*160)+'px"></div><small>'+String(y).slice(2)+'</small></div>').join('');
let c=Object.entries(colors).map(([s,color])=>({s,color,v:count(s)})),angle=0,stops=[];c.forEach(x=>{let next=angle+(n?x.v/n*360:0);if(x.v)stops.push(x.color+' '+angle+'deg '+next+'deg');angle=next});$('donut').style.background=stops.length?'conic-gradient('+stops.join(',')+')':'#edf2f4';$('donutTotal').textContent=n;$('legend').innerHTML=c.map(x=>'<div class="legendrow"><span><i class="dot" style="background:'+x.color+'"></i>'+x.s+'</span><b>'+x.v+' <span style="color:#97a6aa;font-weight:400">('+pct(x.v)+')</span></b></div>').join('');
let pcount={};r.forEach(x=>pcount[x.pbt]=(pcount[x.pbt]||0)+1);let orderedPbts=Object.entries(pcount).sort((a,b)=>b[1]-a[1]);let pbtColorMap=mapColors(orderedPbts.map(x=>x[0]));let top=orderedPbts.slice(0,12);let pmax=Math.max(1,...top.map(x=>x[1]));$('pbtBars').innerHTML=top.length?top.map(([k,v])=>{let color=pbtColorMap[k]||'#e24b55';return '<div class="hrow"><div class="pbtlabel"><span class="swatch" style="background:'+color+'"></span><span>'+esc(k)+'</span></div><div class="track"><div class="fill" style="width:'+(v/pmax*100)+'%;background:'+color+'"></div></div><b style="color:'+color+'">'+v+'</b></div>'}).join(''):'<div class="empty">Tiada data bagi penapis ini.</div>';
$('tbody').innerHTML=r.slice(0,150).map((x,i)=>{let pbtColor=pbtColorMap[x.pbt]||'#c59067';return '<tr class="tbodyrow"><td>'+esc(x.bil||i+1)+'</td><td>'+x.tahun+'</td><td style="border-left:4px solid '+pbtColor+'"><span class="pbtpill" style="background:'+alpha(pbtColor,'18')+';color:'+pbtColor+';border-color:'+alpha(pbtColor,'55')+'"><span class="swatch" style="background:'+pbtColor+'"></span>'+esc(x.pbt)+'</span></td><td title="'+esc(x.tajuk)+'">'+esc(x.tajuk.slice(0,235))+(x.tajuk.length>235?'…':'')+'</td><td>'+esc(x.pemohon)+'</td><td><span class="pill" style="background:'+(colors[x.status]||'#999')+'20;color:'+(colors[x.status]||'#666')+'">'+esc(x.status)+'</span></td></tr>'}).join('')||'<tr><td colspan="6" class="empty">Tiada rekod ditemui.</td></tr>';$('tableCount').textContent='Memaparkan '+Math.min(r.length,150)+' daripada '+r.length+' rekod ditapis.'}
function resetFilters(){['search','year','pbt','status'].forEach(id=>$(id).value='');render()}
function exportCSV(){let header=['Bil','Pemohon','PBT','Tahun','Keputusan','Tajuk','Tarikh Kelulusan'];let cols=['bil','pemohon','pbt','tahun','status','tajuk','kelulusan'];const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';let csv='\ufeff'+[header,...selected().map(r=>cols.map(c=>r[c]))].map(row=>row.map(quote).join(',')).join('\r\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='Rekod_KSAS_Ditapis.csv';a.click();URL.revokeObjectURL(u)}render();
</script></body></html>'''
